  contractSecurity?: Prisma.ContractSecurityOmit;
  contractMilestone?: Prisma.ContractMilestoneOmit;
  payment?: Prisma.PaymentOmit;
  document?: Prisma.DocumentOmit;
  comment?: Prisma.CommentOmit;
